INSERT INTO `categories` VALUES 
(1, NULL, 'Agro Bottles', 'agro-bottles', '/uploads/products/agro-bottles/agro-500ml-agro.webp', '/uploads/products/agro-bottles/agro-500ml-agro.webp', 'Agro & pesticide PET bottles engineered with 46mm tamper-evident neck finishes from 100ml to 1,000ml.', 1, 'published', '2026-09-27 22:50:00'),
(2, NULL, 'Caps', 'caps', '/uploads/products/caps/cap-nb108-a.webp', '/uploads/products/caps/cap-nb108-a.webp', 'Engineered precision screw closures, push-pull caps, flip-top caps, disc-top caps, and CRC closures.', 2, 'published', '2026-09-27 22:50:00'),
(3, NULL, 'Cosmetics Bottles', 'cosmetics-bottles', '/uploads/products/cosmetics-bottles/cosmetic-100ml-tulip.webp', '/uploads/products/cosmetics-bottles/cosmetic-100ml-tulip.webp', 'Cosmetic & personal care PET containers in Veola, Tulip, Badami, Oval, and Boston configurations.', 3, 'published', '2026-09-27 22:50:00'),
(4, NULL, 'Jars', 'jars', '/uploads/products/jars/jar-150cc-rd.webp', '/uploads/products/jars/jar-150cc-rd.webp', 'Wide-mouth round PET jars from 75cc to 500cc for nutraceutical tablets, powders, and cosmetic creams.', 4, 'published', '2026-09-27 22:50:00'),
(5, NULL, 'Pharma Bottles', 'pharma-bottles', '/uploads/products/pharma-bottles/pharma-100ml-dome-pet.webp', '/uploads/products/pharma-bottles/pharma-100ml-dome-pet.webp', 'Cleanroom manufactured pharmaceutical PET bottles for syrups, suspensions, and oral formulations.', 5, 'published', '2026-09-27 22:50:00'),
(6, NULL, 'Pumps', 'pumps', '/uploads/products/pumps/lotion-pump-nb101-a.webp', '/uploads/products/pumps/lotion-pump-nb101-a.webp', 'High-output lotion pumps, treatment dispensers, switch pumps, and foaming dispensers with precision dosage.', 6, 'published', '2026-09-27 22:50:00'),
(7, NULL, 'Sprays', 'sprays', '/uploads/products/sprays/medical-sprayer-nb107-a.webp', '/uploads/products/sprays/medical-sprayer-nb107-a.webp', 'Medical sprayers, fine-mist atomizers, continuous-mist sprayers, and trigger spray systems.', 7, 'published', '2026-09-27 22:50:00');
