INSERT INTO `seo_pages` (`page_type`, `page_ref_id`, `url_slug`, `meta_title`, `meta_description`, `meta_keywords`, `focus_keyword`, `canonical_url`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_image`, `schema_type`, `h1_override`) VALUES
('home', 'home', '/', 'TrueNorth Group — Precision Primary Packaging Partner', 'TrueNorth Group is an ISO 9001 certified primary packaging manufacturer producing high-precision PET bottles, jars, closures, and dispensing pumps for pharma and cosmetics.', '', 'primary packaging manufacturer', '', 1, 1, 'TrueNorth Group — Precision Primary Packaging Partner', 'TrueNorth Group is an ISO 9001 certified primary packaging manufacturer producing high-precision PET bottles, jars, closures, and dispensing pumps for pharma and cosmetics.', '/hero_bottles_banner.webp', 'Organization', ''),
('page', 'about', '/about', 'About Us', '', '', '', '', 1, 1, 'About Us', '', '/hero_bottles_banner.webp', 'WebPage', ''),
('page', 'sustainability', '/sustainability', 'Sustainable rPET & PCR Packaging Solutions — TrueNorth Group', 'Certified food-grade rPET bottles, wide-mouth PCR jars, and lightweighted packaging engineered to reduce carbon footprints without compromising barrier protection.', '', 'sustainable rpet packaging', '', 1, 1, 'Sustainable rPET & PCR Packaging Solutions — TrueNorth Group', 'Certified food-grade rPET bottles, wide-mouth PCR jars, and lightweighted packaging engineered to reduce carbon footprints without compromising barrier protection.', '/hero_bottles_banner.webp', 'AboutPage', ''),
('page', 'products', '/products', 'Products Catalogue — Wholesale PET Bottles, Jars & Pumps', 'Explore precision-molded PET bottles, wide-mouth pharmaceutical jars, tamper-evident caps, and cosmetic lotion pumps with technical drawings and volume pricing.', '', 'wholesale pet bottles', '', 1, 1, 'Products Catalogue — Wholesale PET Bottles, Jars & Pumps', 'Explore precision-molded PET bottles, wide-mouth pharmaceutical jars, tamper-evident caps, and cosmetic lotion pumps with technical drawings and volume pricing.', '/hero_bottles_banner.webp', 'CollectionPage', ''),
('page', 'custom', '/custom', 'Custom Mould Development & Bespoke Packaging — TrueNorth Group', 'End-to-end bespoke packaging engineering: 3D CAD modeling, rapid prototype pilot moulds, custom neck finishes, and commercial blow-mould tooling in 21 days.', '', 'custom bottle moulds', '', 1, 1, 'Custom Mould Development & Bespoke Packaging — TrueNorth Group', 'End-to-end bespoke packaging engineering: 3D CAD modeling, rapid prototype pilot moulds, custom neck finishes, and commercial blow-mould tooling in 21 days.', '/hero_bottles_banner.webp', 'Service', ''),
('page', 'faq', '/faq', 'Frequently Asked Questions & Packaging Specifications — TrueNorth Group', 'Find answers to common questions regarding minimum order quantities (MOQs), food-grade certifications, resin selections, lead times, and global shipping.', '', 'packaging manufacturer faq', '', 1, 1, 'Frequently Asked Questions & Packaging Specifications — TrueNorth Group', 'Find answers to common questions regarding minimum order quantities (MOQs), food-grade certifications, resin selections, lead times, and global shipping.', '/hero_bottles_banner.webp', 'FAQPage', ''),
('page', 'contact', '/contact', 'Contact TrueNorth Group — Global Packaging Sales & Support', 'Connect with our packaging engineers and commercial teams in Delhi, Daman, and Ningbo. Request quotations, technical drawings, and custom tooling.', '', 'packaging manufacturer contact', '', 1, 1, 'Contact TrueNorth Group — Global Packaging Sales & Support', 'Connect with our packaging engineers and commercial teams in Delhi, Daman, and Ningbo. Request quotations, technical drawings, and custom tooling.', '/hero_bottles_banner.webp', 'ContactPage', ''),
('page', 'blog', '/blog', 'Packaging Engineering Insights & Industry Articles — TrueNorth Group', 'In-depth packaging engineering guides, sustainability analyses, rPET regulation updates, and technical insights from TrueNorth Group engineers.', '', 'packaging industry insights', '', 1, 1, 'Packaging Engineering Insights & Industry Articles — TrueNorth Group', 'In-depth packaging engineering guides, sustainability analyses, rPET regulation updates, and technical insights from TrueNorth Group engineers.', '/hero_bottles_banner.webp', 'Blog', ''),
('page', 'terms', '/terms-conditions', 'General Terms & Conditions of Supply — TrueNorth Group', 'Review the commercial terms, quality benchmarks, delivery conditions, and contractual provisions governing TrueNorth Group packaging supply agreements.', '', 'packaging supply terms', 'https://wetruenorthgroup.com/terms-conditions', 1, 1, 'General Terms & Conditions of Supply — TrueNorth Group', 'Review the commercial terms, quality benchmarks, delivery conditions, and contractual provisions governing TrueNorth Group packaging supply agreements.', '/hero_bottles_banner.webp', 'WebPage', ''),
('page', 'privacy', '/privacy-policy', 'Privacy & Data Protection Policy — TrueNorth Group', 'Review how TrueNorth Group handles client proprietary designs, commercial requests, technical NDAs, and digital communication data.', '', 'packaging privacy policy', 'https://wetruenorthgroup.com/privacy-policy', 1, 1, 'Privacy & Data Protection Policy — TrueNorth Group', 'Review how TrueNorth Group handles client proprietary designs, commercial requests, technical NDAs, and digital communication data.', '/hero_bottles_banner.webp', 'WebPage', ''),
('blog', '4', '/blog/choosing-the-right-packaging-for-cosmetics-a-comprehensive-guide', 'Choosing the Right Packaging for Cosmetics: A Comprehensive Guide', 'A comprehensive technical guide to selecting high-clarity PET bottles, luxury acrylic jars, and lotion dispensing pumps for cosmetic and personal care brands.', '', 'cosmetic packaging guide', '', 1, 1, '', '', '/hero_bottles_banner.webp', 'BlogPosting', ''),
('category', 'agro-bottles', '/products/agro-bottles', 'Agro Chemical Bottles — Precision Engineered Containers | TrueNorth Group', 'High-density chemical resistant PET and HDPE agrochemical bottles, pesticide containers, and agricultural liquid packaging with leak-proof closures.', 'agro chemical bottles, packaging, TrueNorth Group', 'agro chemical bottles', 'https://wetruenorthgroup.com/products/agro-bottles', 1, 1, 'Agro Chemical Bottles — Precision Engineered Containers | TrueNorth Group', 'High-density chemical resistant PET and HDPE agrochemical bottles, pesticide containers, and agricultural liquid packaging with leak-proof closures.', '/uploads/products/agro-bottles/agro-500ml-agro.webp', 'CollectionPage', ''),
('category', 'caps', '/products/caps', 'Caps & Closures — Wholesale Tamper-Evident & Dispensing Caps | TrueNorth Group', 'Precision-molded screw caps, disc-top caps, flip-top closures, tamper-evident ROPP seals, and child-resistant closures for cosmetics and pharma.', 'caps and closures wholesale, packaging, TrueNorth Group', 'caps and closures wholesale', 'https://wetruenorthgroup.com/products/caps', 1, 1, 'Caps & Closures — Wholesale Tamper-Evident & Dispensing Caps | TrueNorth Group', 'Precision-molded screw caps, disc-top caps, flip-top closures, tamper-evident ROPP seals, and child-resistant closures for cosmetics and pharma.', '/uploads/products/caps/cap-nb108-a.webp', 'CollectionPage', ''),
('category', 'cosmetics-bottles', '/products/cosmetics-bottles', 'Cosmetics Bottles — Luxury PET & Acrylic Packaging | TrueNorth Group', 'Premium cosmetic PET bottles, lotion containers, serum vials, and personal care packaging with glass-like optical clarity and bespoke color matching.', 'cosmetic bottles manufacturer, packaging, TrueNorth Group', 'cosmetic bottles manufacturer', 'https://wetruenorthgroup.com/products/cosmetics-bottles', 1, 1, 'Cosmetics Bottles — Luxury PET & Acrylic Packaging | TrueNorth Group', 'Premium cosmetic PET bottles, lotion containers, serum vials, and personal care packaging with glass-like optical clarity and bespoke color matching.', '/uploads/products/cosmetics-bottles/cosmetic-100ml-tulip.webp', 'CollectionPage', ''),
