('product', 'LIQ-180ML-ROUND-12G', '/product/liq-180ml-round-12g', '180ml Fluted Round Liquor PET Bottle (180 ml) | Spirits Packaging — TrueNorth Group', 'Wholesale 180ml Fluted Round Liquor PET Bottle (12.5g) from TrueNorth Group. 25mm neck, 143mm height, decorative flutes for premium alcohol shelf appeal.', '180ml Fluted Round Liquor PET Bottle (12.5g), Liquor & Spirits Bottles, primary packaging, TrueNorth Group', '180ml Fluted Round Liquor PET Bottle (12.5g)', 'https://wetruenorthgroup.com/product/liq-180ml-round-12g', 1, 1, '180ml Fluted Round Liquor PET Bottle (180 ml) | Spirits Packaging — TrueNorth Group', 'Wholesale 180ml Fluted Round Liquor PET Bottle (12.5g) from TrueNorth Group. 25mm neck, 143mm height, decorative flutes for premium alcohol shelf appeal.', '/uploads/products/liquor-bottles/liq-180ml-round-12g.webp', 'Product', ''),
('industry', 'cosmetics', '/products/cosmetics', 'Cosmetics & Personal Care Packaging | TrueNorth Group', 'Premium aesthetic PET bottles, luxury dispensing pumps, fine mist atomizers, and cosmetic jars crafted for skincare, haircare, and personal care brands.', '', 'cosmetics packaging', 'https://wetruenorthgroup.com/products/cosmetics', 1, 1, 'Cosmetics & Personal Care Packaging | TrueNorth Group', 'Premium aesthetic PET bottles, luxury dispensing pumps, fine mist atomizers, and cosmetic jars crafted for skincare, haircare, and personal care brands.', '/vikaas_inputs/COSMETICS.webp', 'CollectionPage', ''),
('industry', 'pharma', '/products/pharmaceuticals', 'Pharmaceuticals & Healthcare Packaging | TrueNorth Group', 'Cleanroom-manufactured USP Class VI oral syrup bottles, CRC child-resistant closures, amber UV-protective bottles, and medical dispensing solutions.', '', 'pharma packaging bottles', 'https://wetruenorthgroup.com/products/pharmaceuticals', 1, 1, 'Pharmaceuticals & Healthcare Packaging | TrueNorth Group', 'Cleanroom-manufactured USP Class VI oral syrup bottles, CRC child-resistant closures, amber UV-protective bottles, and medical dispensing solutions.', '/vikaas_inputs/PHARMA_BOTTLES.webp', 'CollectionPage', ''),
('industry', 'agro', '/products/agrochemicals', 'Agrochemicals & Pesticides Packaging | TrueNorth Group', 'High-barrier PET & HDPE containers, tamper-evident 46mm agro neck finishes, and chemical-resistant closures designed for agrochemicals and pesticides.', '', 'agrochemical packaging containers', 'https://wetruenorthgroup.com/products/agrochemicals', 1, 1, 'Agrochemicals & Pesticides Packaging | TrueNorth Group', 'High-barrier PET & HDPE containers, tamper-evident 46mm agro neck finishes, and chemical-resistant closures designed for agrochemicals and pesticides.', '/vikaas_inputs/AGRO_PESTICIDES.webp', 'CollectionPage', ''),
('industry', 'nutraceuticals', '/products/nutraceuticals', 'Nutraceuticals & Health Supplements Packaging | TrueNorth Group', 'Wide-mouth round PET jars and packer bottles from 75cc to 500cc engineered for tablets, capsules, nutritional powders, and wellness supplements.', '', 'nutraceutical jars packaging', 'https://wetruenorthgroup.com/products/nutraceuticals', 1, 1, 'Nutraceuticals & Health Supplements Packaging | TrueNorth Group', 'Wide-mouth round PET jars and packer bottles from 75cc to 500cc engineered for tablets, capsules, nutritional powders, and wellness supplements.', '/vikaas_inputs/PET_nutraceuticle_jars.webp', 'CollectionPage', ''),
('industry', 'liquor', '/products/liquor', 'Liquor, Spirits & Beverages Packaging | TrueNorth Group', 'Crystal-clear PET pocket flasks, flat liquor containers, round spirits bottles, and beverage packaging engineered for premium shelf appeal and shatter resistance.', '', 'liquor spirits pet bottles', 'https://wetruenorthgroup.com/products/liquor', 1, 1, 'Liquor, Spirits & Beverages Packaging | TrueNorth Group', 'Crystal-clear PET pocket flasks, flat liquor containers, round spirits bottles, and beverage packaging engineered for premium shelf appeal and shatter resistance.', '/vikaas_inputs/LIQUOR_Bottles.webp', 'CollectionPage', '')
